@using sv_61e0c8d0686b450baa1a7f3d0870491e.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm" value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseChanged" style="width: 220px;">
    @foreach (var wh in WarehouseStateService.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

@using sv_61e0c8d0686b450baa1a7f3d0870491e.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-auto">0</span>
}

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertChanged;
    }

    private void HandleAlertChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
    }
}

