@page "/dashboard"
@rendermode InteractiveServer
@using sv_61e0c8d0686b450baa1a7f3d0870491e.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard – @WarehouseState.CurrentWarehouse.Name</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-5">
            <strong>@WarehouseState.CurrentWarehouse.Name</strong>
            <span class="text-muted">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.CurrentAlertCount > 0)
            {
                <span class="fs-3 text-danger fw-bold">@AlertService.CurrentAlertCount</span>
                <span class="text-muted ms-2">items below minimum stock level</span>
            }
            else
            {
                <span class="fs-3 text-success fw-bold">0</span>
                <span class="text-muted ms-2">all stock levels healthy</span>
            }
        </p>
        <small class="text-muted">Auto-refreshes every 10 seconds while this page is open.</small>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleStateChanged;

        // Start polling — the service tracks subscriber count and manages the timer.
        AlertService.Subscribe();
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertCountChanged -= HandleStateChanged;
        AlertService.Unsubscribe();
    }
}

